async function uploadProfileMedia(file,kind){
  if(!supabaseClient||!supabaseUser)throw new Error('Войди в аккаунт Supabase, чтобы загрузить файл в облако.');
  const rawExt=(String(file.name||'').split('.').pop()||'bin').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,8)||'bin';
  const ext=kind==='avatar'||kind==='cover'?'jpg':rawExt;
  const path=`${supabaseUser.id}/${kind}-${Date.now()}-${Math.random().toString(36).slice(2,8)}.${ext}`;
  const contentType=file.type|| (kind==='avatar'||kind==='cover'?'image/jpeg':'application/octet-stream');
  const {error}=await supabaseClient.storage.from(PROFILE_MEDIA_BUCKET).upload(path,file,{contentType,upsert:false});
  if(error)throw new Error('Не удалось загрузить файл в Supabase Storage: '+error.message);
  const {data}=supabaseClient.storage.from(PROFILE_MEDIA_BUCKET).getPublicUrl(path);
  if(!data?.publicUrl)throw new Error('Supabase не вернул публичную ссылку на файл.');
  return data.publicUrl;
}
