  const payload={id:user.id,username:existing?.username||null,display_name:name||existing?.display_name||user.user_metadata?.display_name||base,
    bio:existing?.bio??'',avatar_url:existing?.avatar_url??null,music_url:existing?.music_url??null,music_title:existing?.music_title??null,music_cover_url:existing?.music_cover_url??null,profile_cover_url:existing?.profile_cover_url??null,profile_cover_color:existing?.profile_cover_color??null};
  const {data,error}=await supabaseClient.from('profiles').upsert(payload,{onConflict:'id'}).select('id,username,display_name,bio,avatar_url,music_url,music_title,music_cover_url,profile_cover_url,profile_cover_color').maybeSingle();
  if(error){console.warn('Supabase profile:',error.message);return existing;}
