const presenceTabId=(crypto.randomUUID?.()||String(Date.now())+Math.random());
const presencePrefix='gt_presence_';
const remotePresence=new Map();
let presenceBusy=false, presencePollBusy=false;
function presenceKey(){return currentUser?.email?presencePrefix+currentUser.email.toLowerCase():null}
async function publishPresence(){
 if(!supabaseClient||!supabaseUser||presenceBusy)return;
 presenceBusy=true;
 try{
  const {error}=await supabaseClient.from('user_presence').upsert(
   {user_id:supabaseUser.id,last_seen:new Date().toISOString()},{onConflict:'user_id'});
  if(error){console.error('Presence heartbeat:',error); window.mashixPresenceError=error.message; }else{window.mashixPresenceError='';window.mashixPresenceLastWrite=new Date().toISOString();}
 }catch(e){console.warn('Presence heartbeat:',e)}
 finally{presenceBusy=false}
}
async function leavePresence(){
 // Не удаляем last_seen: оно необходимо для корректного отображения последнего визита.
 // Другие вкладки/устройства того же пользователя могут оставаться открытыми.
}
function getPresenceRecord(c){
 const id=String(c?.id||'');
 return remotePresence.get(id)||null;
}
function isOnline(c){
 if(window.mashixPrivacyCanSeeOnline&&!window.mashixPrivacyCanSeeOnline())return false;
 const v=getPresenceRecord(c);
 return !!v&&Number.isFinite(Number(v.at))&&Date.now()-Number(v.at)<20000;
}
async function pollRemotePresence(){
 if(!supabaseClient||!supabaseUser||presencePollBusy)return;
 const ids=[...new Set(contacts.filter(c=>c&&!c.isFavorites&&(!c.mashixType||c.mashixType==='user')&&/^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(String(c.id))).map(c=>String(c.id)))];
 if(!ids.length)return;
 presencePollBusy=true;
 try{
  const {data,error}=await supabaseClient.from('user_presence').select('user_id,last_seen').in('user_id',ids);
  if(error)throw error;
  for(const r of data||[])remotePresence.set(String(r.user_id),{at:Date.parse(r.last_seen)});
  refreshPresence();
 }catch(e){console.warn('Presence read:',e)}
 finally{presencePollBusy=false}
}
function formatLastSeen(timestamp){
 const d=new Date(timestamp),now=new Date();
 if(!Number.isFinite(d.getTime()))return '';
 const minutes=Math.max(0,Math.floor((now-d)/60000));
 if(minutes<1)return 'был(а) только что';
 if(minutes<60){
  const form=minutes%10===1&&minutes%100!==11?'минуту':minutes%10>=2&&minutes%10<=4&&(minutes%100<12||minutes%100>14)?'минуты':'минут';
  return `был(а) ${minutes} ${form} назад`;
 }
 const time=d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
 if(d.toDateString()===now.toDateString())return `был(а) в ${time}`;
 const yesterday=new Date(now);yesterday.setDate(now.getDate()-1);
 if(d.toDateString()===yesterday.toDateString())return `был(а) вчера в ${time}`;
 return `был(а) ${d.toLocaleDateString('ru-RU',{day:'numeric',month:'short'})} в ${time}`;
}
function statusMarkup(c){return `<span class="presence-dot ${isOnline(c)?'online':''}" aria-label="${isOnline(c)?'онлайн':'оффлайн'}"></span>`}
function updateActivePresence(){if(!activeChat)return;const c=contacts.find(x=>String(x.id)===String(activeChat));const type=c?.mashixType;const label=$('#activePresenceText');const dot=$('#activePresenceDot');const favorites=!!(c?.isFavorites||String(activeChat)==='mashix_favorites');if(favorites){dot.hidden=true;dot.classList.remove('online');label.hidden=true;label.textContent='';return}label.hidden=false;if(type==='channel'||type==='group'){dot.hidden=true;dot.classList.remove('online');const count=(Array.isArray(c.memberIds)?new Set(c.memberIds.map(String)).size:0)+1;label.textContent=type==='channel'?`${count} подписчик${count===1?'':'а'}`:`${count} участник${count===1?'':'а'}`;label.className='last';return}dot.hidden=false;const online=isOnline(c);dot.classList.toggle('online',online);const record=getPresenceRecord(c);const lastSeen=record&&Number.isFinite(Number(record.at))?formatLastSeen(Number(record.at)):'';label.textContent=online?'в сети':(lastSeen||'давно не в сети');label.className='last '+(online?'status-online':'status-offline')}
function refreshPresence(){
  // Не перерисовываем списки целиком каждые 4 секунды: это сбрасывало
  // DOM-элементы и анимации, из-за чего чаты/контакты визуально мигали.
  // Обновляем только индикаторы присутствия на уже созданных элементах.
  const updateDots=(selector)=>{
    $$(selector).forEach(dot=>{
      const row=dot.closest('[data-id]');
      if(!row)return;
      const contact=allContacts().find(c=>String(c.id)===String(row.dataset.id));
      if(!contact)return;
      if(contact.isFavorites||String(contact.id)==='mashix_favorites'){dot.hidden=true;dot.classList.remove('online');return;}
      dot.hidden=false;
      const online=isOnline(contact);
      dot.classList.toggle('online',online);
      dot.setAttribute('aria-label',online?'онлайн':'оффлайн');
    });
  };
  updateDots('#chatList .presence-dot');
  updateDots('#contactList .presence-dot');
  updateActivePresence();
}
