window.addEventListener('storage',e=>{
  if(e.key?.startsWith(presencePrefix))refreshPresence();
  else if(e.key==='gt_chats'){
    chats=read('gt_chats',{});
    if(activeChat)renderMessages();
    // Обновляем превью последнего сообщения без пересоздания списка.
    $$('#chatList .chat-row').forEach(row=>{
      const preview=row.querySelector('.last');
      if(preview)preview.textContent=lastText(row.dataset.id);
    });
  }else if(e.key==='gt_contacts'){
    const storedContacts=read('gt_contacts',defaultContacts);
    contacts=Array.isArray(storedContacts)?storedContacts.filter(c=>c&&typeof c==='object'&&!Array.isArray(c)&&c.id!=null):defaultContacts.map(c=>({...c}));
    if(!contacts.some(c=>String(c.id)==='mashix_favorites'))contacts.unshift({id:'mashix_favorites',name:'Избранное',avatar:'⭐',about:'Твои сохранённые сообщения и заметки',isFavorites:true});
    const fav=contacts.find(c=>c&&(c.isFavorites||String(c.id)==='mashix_favorites'||String(c.name||'').trim().toLowerCase()==='избранное'));if(fav){fav.isFavorites=true;delete fav.username;delete fav.email;delete fav.phone;}
    renderContacts();renderChats();
  }
});
