function safe(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function userKey(){return currentUser?.email||'guest'}
function keyFor(id){return userKey()+'::'+id}
function getMsgs(id){const value=chats[keyFor(id)];return Array.isArray(value)?value:[]}
function saveMsgs(id,arr){
  // Перед записью перечитываем последнюю версию и обновляем только нужный диалог.
  // Так изменения в других чатах/вкладках не затираются устаревшим объектом.
  const latest=read('gt_chats',{});
  const base=latest&&typeof latest==='object'&&!Array.isArray(latest)?latest:{};
  const key=keyFor(id);
  const next={...base,[key]:Array.isArray(arr)?arr:[]};
  if(write('gt_chats',next))chats=next;
}
window.addEventListener('storage',e=>{
  if(e.key==='gt_chats'){
    chats=read('gt_chats',{});
    if(activeChat)renderMessages();
    renderChats();
  }else if(e.key==='gt_contacts'){
    contacts=read('gt_contacts',defaultContacts);
    renderContacts();renderChats();
    if(activeChat&&!contacts.some(c=>c.id===activeChat)){
      activeChat=null;$('#chatScreen').classList.remove('show');
    }
  }else if(e.key==='gt_users'){
    const storedUsers=read('gt_users',[]);
    users=Array.isArray(storedUsers)?storedUsers.filter(u=>u&&typeof u==='object'&&!Array.isArray(u)):[];
  }
});
