$('#authForm').addEventListener('submit',async e=>{
 e.preventDefault();
 const email=$('#authEmail').value.trim().toLowerCase(), password=$('#authPassword').value, name=$('#authName').value.trim();
 const err=$('#authError'); err.textContent='';
 if(!supabaseClient){err.textContent='Не удалось загрузить модуль подключения. Обнови страницу и попробуй снова.';return;}
 const submit=$('#authSubmit');submit.disabled=true;submit.textContent='Подожди…';
 try{
   let result;
   if(mode==='register'){
     if(!name){err.textContent='Введи имя.';return;}
     result=await supabaseClient.auth.signUp({email,password,options:{data:{display_name:name}}});
     if(result.error)throw result.error;
     if(!result.data.session){
       err.textContent='Аккаунт создан. Проверь почту и подтверди адрес, затем войди.';
       return;
     }
     supabaseUser=result.data.user;
     await saveRemoteProfile(supabaseUser,name);
   }else{
     result=await supabaseClient.auth.signInWithPassword({email,password});
     if(result.error)throw result.error;
     supabaseUser=result.data.user;
     await saveRemoteProfile(supabaseUser,supabaseUser.user_metadata?.display_name||email.split('@')[0]);
   }
   const remoteProfile=await fetchRemoteProfile(supabaseUser);
   currentUser={id:supabaseUser.id,email:supabaseUser.email,name:remoteProfile?.display_name||name||supabaseUser.user_metadata?.display_name||email.split('@')[0],username:remoteProfile?.username||'',about:remoteProfile?.bio||'',photo:remoteProfile?.avatar_url||null,musicUrl:remoteProfile?.music_url||null,musicTitle:remoteProfile?.music_title||'',musicCoverUrl:remoteProfile?.music_cover_url||null,coverImage:remoteProfile?.profile_cover_url||null,coverColor:remoteProfile?.profile_cover_color||''};
   document.body.classList.add('authenticated');$('#auth').style.display='none';await publishPresence();updateProfile();renderProfileMusic();renderChats();renderContacts();pollRemotePresence();
   hydrateRemoteContactProfiles().then(()=>{renderChats();renderContacts()});
   if(typeof subscribeToRemoteMessages==='function')subscribeToRemoteMessages();
 }catch(error){
   console.error('Supabase auth:',error);
   err.textContent=error.message||'Не удалось выполнить вход. Проверь email и пароль.';
 }finally{
   submit.disabled=false;submit.textContent=mode==='register'?'Создать аккаунт':'Войти';
 }
});
