$('#profileCoverInput').addEventListener('change',async e=>{
  const input=e.target,file=input.files&&input.files[0];input.value='';
  if(!file||!currentUser)return;
  if(!file.type.startsWith('image/'))return alert('Выбери файл изображения.');
  const hint=$('#photoHint');if(hint)hint.textContent='Обрабатываю фон профиля…';
  try{
    const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать изображение'));reader.readAsDataURL(file)});
    const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Не удалось открыть изображение'));image.src=dataUrl});
    const canvas=document.createElement('canvas'),max=1200,scale=Math.min(1,max/Math.max(img.width,img.height));
    canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
    canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
    const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Не удалось обработать изображение')),'image/jpeg',.82));
    let coverUrl=canvas.toDataURL('image/jpeg',.82);
    if(supabaseClient&&supabaseUser){
      coverUrl=await uploadProfileMedia(new File([blob],'profile-background.jpg',{type:'image/jpeg'}),'cover');
      await saveRemoteProfileFields({profile_cover_url:coverUrl,profile_cover_color:null});
    }
    currentUser.coverImage=coverUrl;currentUser.coverColor='';
    users=users.map(u=>u.email===currentUser.email?{...u,coverImage:coverUrl,coverColor:''}:u);write('gt_users',users);
    applyProfileCover();
    if(hint)hint.textContent=supabaseUser?'Фон сохранён в облаке и будет виден другим пользователям.':'Фон сохранён на этом устройстве.';
  }catch(err){console.error('Фон профиля:',err);if(hint)hint.textContent='Не удалось сохранить фон: '+(err.message||'ошибка');}
});
