function allContacts(){
  // «Избранное» — системный чат, остальные контакты показываем без дубликатов,
  // созданных из старого email-псевдонима вида username_7e8711.
  const ownIds=new Set([String(supabaseUser?.id||''),String(currentUser?.id||'')].filter(Boolean));
  const ownEmails=new Set([String(supabaseUser?.email||''),String(currentUser?.email||'')].map(v=>v.toLowerCase()).filter(Boolean));
  const normName=c=>String(c?.name||'').trim().toLocaleLowerCase().replace(/\s+/g,' ');
  const generated=c=>/_[a-f0-9]{5,}$/i.test(String(c?.username||'').replace(/^@/,''));
  return contacts.filter(c=>{
    if(c?.isFavorites||String(c?.id)==='mashix_favorites')return true;
    if(ownIds.has(String(c?.id||'')))return false;
    if(c?.isRemote && c?.email && ownEmails.has(String(c.email).toLowerCase()))return false;
    if(generated(c) && contacts.some(other=>other!==c && normName(other)===normName(c) && !generated(other) && (other.isRemote || /^[0-9a-f-]{36}$/i.test(String(other.id||'')))))return false;
    return true;
  });
}
function lastText(id){let a=getMsgs(id);if(!a.length)return 'Начни новый разговор ✨';const m=a[a.length-1];return m.text||(m.attachmentType&&m.attachmentType.startsWith('image/')?'🖼️ Фото':m.attachmentType&&m.attachmentType.startsWith('video/')?'🎬 Видео':m.attachmentType&&m.attachmentType.startsWith('audio/')?'🎵 Музыка':m.attachmentId?'📎 Файл':m.audioData?'🎙️ Голосовое сообщение':'') }

function contactPhoto(c){if(!c)return '';const candidates=[c.photo,c.profilePhoto,c.avatarUrl,c.avatar_url,c.photo_url,c.profilePhotoUrl,c.profile_photo_url,c.profile&&c.profile.avatar_url,c.user_metadata&&c.user_metadata.avatar_url,typeof c.avatar==='string'&&(/^data:image\//i.test(c.avatar)||/^https?:\/\//i.test(c.avatar))?c.avatar:''];return candidates.find(v=>typeof v==='string'&&v.trim())||''}
function contactAvatarMarkup(c,fallback='👤',presence=true){const photo=contactPhoto(c);return `${photo?`<img src="${safe(photo)}" alt="Аватар" style="display:block;width:100%;height:100%;object-fit:cover;border-radius:inherit">`:safe(fallback)}${presence?statusMarkup(c):''}`}
// Hydrate locally saved chat/contact rows with cloud profile photos and names.
// Existing contacts may have been added before avatar_url was included in search results.
let remoteAvatarHydrationPromise=null;
async function hydrateRemoteContactProfiles(){
  if(!supabaseClient||!supabaseUser)return;
  if(remoteAvatarHydrationPromise)return remoteAvatarHydrationPromise;
  remoteAvatarHydrationPromise=(async()=>{
    const ids=[...new Set((contacts||[]).filter(c=>c&&!['group','channel'].includes(c.mashixType)&&isUuid(c.id)&&String(c.id)!==String(supabaseUser.id)).map(c=>String(c.id)))];
    if(!ids.length)return;
    for(let i=0;i<ids.length;i+=100){
      const batch=ids.slice(i,i+100);
      const {data,error}=await supabaseClient.from('profiles').select('id,username,display_name,avatar_url,bio').in('id',batch);
      if(error){console.warn('Не удалось загрузить аватары контактов:',error.message);continue;}
      let changed=false;
      for(const profile of data||[]){
        const c=contacts.find(x=>String(x.id)===String(profile.id));if(!c)continue;
        if(profile.avatar_url && c.photo!==profile.avatar_url){c.photo=profile.avatar_url;c.avatar_url=profile.avatar_url;c.avatarUrl=profile.avatar_url;changed=true;}
        if(profile.username && !c.username){c.username=profile.username;changed=true;}
        if(profile.display_name && (!c.name || c.name===c.username || c.name==='💬')){c.name=profile.display_name;changed=true;}
        if(profile.bio && !c.bio){c.bio=profile.bio;changed=true;}
      }
      if(changed)write('gt_contacts',contacts);
    }
  })().finally(()=>{remoteAvatarHydrationPromise=null;});
  return remoteAvatarHydrationPromise;
}
function renderChats(){let q=$('#chatSearch').value.toLowerCase().trim().replace(/^@/,'');let list=allContacts().filter(c=>(c.name+' '+(c.surname||'')+' '+(c.email||'')+' '+(c.username||'')+' '+(c.description||'')+' '+(c.bio||'')+' '+(c.about||'')+' '+(c.mashixType||'')).toLowerCase().includes(q));list.sort((a,b)=>Number(chatMeta(b.id).pinned)-Number(chatMeta(a.id).pinned));$('#chatList').innerHTML=list.map(c=>{const meta=chatMeta(c.id);return `<div class="chat-row ${meta.pinned?'chat-pinned':''}" data-id="${safe(c.id)}"><div class="avatar presence-avatar">${contactAvatarMarkup(c,c.mashixType==='group'?'🟣':c.mashixType==='channel'?'📣':(c.avatar||'💬'),!['group','channel'].includes(c.mashixType)&&!(c.isFavorites||String(c.id)==='mashix_favorites'||String(c.name||'').trim().toLowerCase()==='избранное'))}</div><div class="chat-info"><div class="chat-name">${meta.pinned?'📌 ':''}${safe(c.name)} ${meta.unread?'<span class="unread-badge">'+meta.unread+'</span>':''}</div><div class="last">${safe(lastText(c.id))}</div></div><div class="time">›</div></div>`}).join('')||'<div class="empty"><div class="emoji">💭</div>Пока ничего нет</div>';$$('#chatList .chat-row').forEach(el=>el.onclick=e=>{if(e.target.closest('button'))return;openPublicProfile(el.dataset.id)});$$('[data-open-chat]').forEach(b=>b.onclick=e=>{e.stopPropagation();openChat(b.dataset.openChat)});$$('[data-pin-chat]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.pinChat,m=chatMeta(id);m.pinned=!m.pinned;setChatMeta(id,m);renderChats()})}
