function formatMessageTime(value){const date=new Date(Number(value)||Date.now());return date.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}
let editingMessageIndex=null;
function renderMessages(){
  const messagesEl=$('#messages');
  // Сохраняем позицию чтения: обновления синхронизации не должны выбрасывать пользователя вниз/вверх.
  const previousScrollTop=messagesEl?messagesEl.scrollTop:0;
  const previousScrollHeight=messagesEl?messagesEl.scrollHeight:0;
  const previousClientHeight=messagesEl?messagesEl.clientHeight:0;
  const wasNearBottom=messagesEl?(previousScrollHeight-previousClientHeight-previousScrollTop<100):true;
  const arr=getMsgs(activeChat);
  const activeContact=contacts.find(x=>String(x.id)===String(activeChat));
  const isChannel=activeContact?.mashixType==='channel';
  const composerInput=$('#messageInput'); if(composerInput) composerInput.placeholder=isChannel?'Создать пост...':'Написать сообщение…';
  $('#messages').innerHTML=arr.length?arr.map((m,i)=>{
    const own=!!m.mine, editing=editingMessageIndex===i&&own;
    const body=editing
      ? `<div class="message-edit"><textarea data-edit-text="${i}" maxlength="4000" aria-label="Редактировать сообщение">${safe(m.text)}</textarea><div class="message-edit-actions"><button class="secondary" type="button" data-cancel-edit>Отмена</button><button class="primary" type="button" data-save-edit="${i}">Сохранить</button></div></div>`
      : `${m.replyTo?`<div class="reply-quote"><b>${safe(m.replyToName?'Ответ '+m.replyToName:'Ответ на сообщение')}</b><div>${safe(m.replyTo)}</div></div>`:''}${m.audioData?`<div class="message-body voice-message"><div class="voice-title"><span class="voice-icon">🎙️</span><span>Голосовое сообщение</span><span class="voice-duration">${Math.floor((Number(m.duration)||0)/60)}:${String((Number(m.duration)||0)%60).padStart(2,"0")}</span></div><audio controls preload="metadata" src="${m.audioData}"></audio><div class="voice-tools"><button type="button" class="voice-speed" title="Скорость воспроизведения">1×</button></div></div>`:`<div class="message-body">${safe(m.text||'')}</div>`}`;
    const actions=!editing?`<div class="message-actions" data-message-menu="${i}"><button class="message-action" type="button" data-reply-message="${i}">↩ Ответить</button><button class="message-action" type="button" data-pin-message="${i}">${m.pinned?"📌 Открепить":"📌 Закрепить"}</button><button class="message-action" type="button" data-copy-message="${i}">▢ Копировать</button><button class="message-action" type="button" data-forward-message="${i}">↗ Переслать</button>${own?`<button class="message-action" type="button" data-edit-message="${i}" aria-label="Редактировать сообщение">✎ Изменить</button><button class="message-action" type="button" data-delete-message="${i}" aria-label="Удалить сообщение">🗑 Удалить</button>`:''}</div>`:'';
    const channelStats=!editing&&isChannel?`<div class="channel-post-actions"><span>👁 ${Number(m.views)||1} просмотров</span><span>↗ ${Number(m.forwards)||0} пересылок</span></div>`:'';
    const reactions=m.reactions&&typeof m.reactions==='object'?m.reactions:{};
    const reactionMarkup=Object.entries(reactions).filter(([emoji,count])=>count>0).map(([emoji,count])=>`<button type="button" class="reaction-chip" data-react="${i}" data-reaction="${safe(emoji)}">${safe(emoji)} ${count}</button>`).join('');
    const reactionPicker='';
    return `<div class="bubble ${own?'mine':'theirs'} ${isChannel?'channel-post':''} ${m.pinned?'message-pinned':''}" data-message-index="${i}" data-message-id="${safe(m.remoteId||m.id||'')}" data-chat-id="${safe(activeChat||'')}" data-reaction-cloud="${activeContact?.mashixType==='group'||activeContact?.mashixType==='channel'?'false':'true'}">${m.pinned?'<div class="message-pinned-label">📌 Закреплённое сообщение</div>':''}${isChannel?'<div class="channel-post-label">📣 Пост канала</div>':''}${m.forwarded?`<div class="channel-post-label">↗ Переслано от ${safe(m.forwardedFrom||'пользователя')}</div>`:''}${activeContact?.mashixType==='group'?`<div class="group-sender-name" style="font-size:12px;font-weight:700;color:${own?'var(--accent)':'#8ecbff'};margin:0 0 5px">${safe(m.senderName||(own?(currentUser?.name||currentUser?.username||supabaseUser?.user_metadata?.display_name||'Вы'):'Участник'))}</div>`:''}${m.attachmentPath?`<div class="mashix-attachment" data-media-path="${safe(m.attachmentPath)}" data-media-type="${safe(m.attachmentType||'')}" data-media-name="${safe(m.attachmentName||'Файл')}"><span>📎 ${safe(m.attachmentName||'Файл')}</span><small>Загрузка файла…</small></div>`:m.attachmentId?`<div class="mashix-attachment" data-media-id="${safe(m.attachmentId)}" data-media-type="${safe(m.attachmentType||'')}" data-media-name="${safe(m.attachmentName||'Файл')}"><span>📎 ${safe(m.attachmentName||'Файл')}</span><small>Загрузка файла…</small></div>`:''}${body}${reactionMarkup?`<div class="message-reactions">${reactionMarkup}</div>`:''}${!editing?reactionPicker:''}${actions}${channelStats}<span class="message-time">${m.edited?'изменено · ':''}${formatMessageTime(m.at)}${own?` <span class="message-receipt ${m.read?'is-read':''}" title="${m.read?'Прочитано':'Отправлено'}" aria-label="${m.read?'Прочитано':'Отправлено'}">${(activeContact?.isFavorites||String(activeChat)==='mashix_favorites'||m.read)?'✓✓':'✓'}</span>`:''}</span></div>`;
  }).join(''):`<div class="empty"><div class="emoji">${isChannel?'📣':(activeContact?.mashixType==='group'?'👥':'✧')}</div>${isChannel?'Здесь пока нет публикаций. Напиши первый пост!':(activeContact?.mashixType==='group'?'Здесь пока нет сообщений в группе. Начни общение!':'Это избранное, тут ты можешь хранить всё!')}</div>`;
  // Автопрокрутка только если пользователь уже читал последние сообщения.
  // Иначе сохраняем точку чтения при входящих сообщениях и обновлениях чата.
  if(messagesEl){
    if(wasNearBottom) messagesEl.scrollTop=messagesEl.scrollHeight;
    else messagesEl.scrollTop=previousScrollTop+(messagesEl.scrollHeight-previousScrollHeight);
  }
}
function finishMessageEdit(index){
  if(!activeChat)return;
  const arr=getMsgs(activeChat), message=arr[index];
  const field=$(`#messages [data-edit-text="${index}"]`);
  if(!message||!message.mine||!field)return;
  const text=field.value.trim();
  if(!text){field.focus();field.setCustomValidity('Сообщение не может быть пустым.');field.reportValidity();return}
  if(text!==message.text){message.text=text;message.edited=true;message.editedAt=Date.now();saveMsgs(activeChat,arr);renderChats()}
  editingMessageIndex=null;renderMessages();
}
