messagesContainer.addEventListener('contextmenu',e=>{const bubble=e.target.closest('.bubble');if(!bubble)return;e.preventDefault();document.querySelectorAll('.bubble.menu-open').forEach(b=>b.classList.remove('menu-open'));bubble.classList.add('menu-open')});
messagesContainer.addEventListener('click',e=>{
  if(longPressTriggered){e.preventDefault();e.stopPropagation();longPressTriggered=false;return}
  const clickedBubble=e.target.closest('.bubble');
  if(clickedBubble&&!e.target.closest('button,textarea,input')){const wasOpen=clickedBubble.classList.contains('menu-open');document.querySelectorAll('.bubble.menu-open').forEach(b=>b.classList.remove('menu-open'));if(!wasOpen)clickedBubble.classList.add('menu-open');return}
  const forward=e.target.closest('[data-forward-message]');
  if(forward){
    forward.closest('.bubble')?.classList.remove('menu-open');
    const index=Number(forward.dataset.forwardMessage), source=getMsgs(activeChat)[index], list=contacts.filter(c=>String(c.id)!==String(activeChat));
    if(!source||!list.length){alert('Нет доступных чатов для пересылки.');return}
    const choices=list.map((c,i)=>`${i+1}. ${c.name||c.username||'Чат'}${c.mashixType==='channel'?' (канал)':c.mashixType==='group'?' (группа)':''}`).join('\n');
    const answer=prompt('Куда переслать? Введи номер из списка:\n'+choices);
    if(answer===null)return;
    const target=list[Number(answer)-1];
    if(!target){alert('Неверный номер чата.');return}
    const targetMsgs=getMsgs(target.id);
    targetMsgs.push({...source,id:undefined,mine:true,at:Date.now(),read:false,edited:false,forwarded:true,forwardedFrom:activeContact?.name||activeContact?.username||'Пересланное сообщение',views:undefined,forwards:undefined,reactions:{}});
    saveMsgs(target.id,targetMsgs);
    if(activeContact?.mashixType==='channel') {source.forwards=(Number(source.forwards)||0)+1;saveMsgs(activeChat,getMsgs(activeChat));}
    renderMessages();renderChats();alert('Сообщение переслано.');
    return;
  }
  const reply=e.target.closest('[data-reply-message]');
  if(reply){reply.closest('.bubble')?.classList.remove('menu-open');const m=getMsgs(activeChat)[Number(reply.dataset.replyMessage)];if(m){pendingReply=m.text;window.pendingReplyName=m.senderName||(m.mine?(currentUser?.name||currentUser?.username||'Вы'):'Участник');$('#messageInput').placeholder='Ответ на: '+m.text.slice(0,42);$('#messageInput').focus()}return}
  const copy=e.target.closest('[data-copy-message]');
  if(copy){copy.closest('.bubble')?.classList.remove('menu-open');const m=getMsgs(activeChat)[Number(copy.dataset.copyMessage)];if(m){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(m.text).catch(()=>prompt('Скопируй сообщение:',m.text));else prompt('Скопируй сообщение:',m.text)}return}
  const react=e.target.closest('[data-react]');
  if(react){const index=Number(react.dataset.react),emoji=react.dataset.reaction,arr=getMsgs(activeChat),message=arr[index];if(!message)return;message.reactions=message.reactions&&typeof message.reactions==='object'?message.reactions:{};message.reactions[emoji]=(message.reactions[emoji]||0)+1;saveMsgs(activeChat,arr);renderMessages();return}
  const edit=e.target.closest('[data-edit-message]');
  if(edit){edit.closest('.bubble')?.classList.remove('menu-open');editingMessageIndex=Number(edit.dataset.editMessage);renderMessages();const field=$(`#messages [data-edit-text="${editingMessageIndex}"]`);if(field){field.focus();field.setSelectionRange(field.value.length,field.value.length)}return}
  if(e.target.closest('[data-cancel-edit]')){editingMessageIndex=null;renderMessages();return}
  const save=e.target.closest('[data-save-edit]');
  if(save){finishMessageEdit(Number(save.dataset.saveEdit));return}
  const del=e.target.closest('[data-delete-message]');
  if(del){del.closest('.bubble')?.classList.remove('menu-open');const index=Number(del.dataset.deleteMessage),arr=getMsgs(activeChat),message=arr[index];if(!message||!message.mine)return;if(!confirm('Удалить это сообщение?'))return;arr.splice(index,1);saveMsgs(activeChat,arr);editingMessageIndex=null;renderMessages();renderChats()}
});
$('#messages').addEventListener('click',e=>{const btn=e.target.closest('[data-forward-post]');if(!btn)return;const idx=Number(btn.dataset.forwardPost),arr=getMsgs(activeChat),post=arr[idx];if(!post)return;post.forwards=(Number(post.forwards)||0)+1;saveMsgs(activeChat,arr);renderMessages()});
$('#messages').addEventListener('keydown',e=>{if(e.target.matches('[data-edit-text]')&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();finishMessageEdit(Number(e.target.dataset.editText))}if(e.target.matches('[data-edit-text]')&&e.key==='Escape'){editingMessageIndex=null;renderMessages()}});
$('#emojiToggle').addEventListener('click',()=>{const panel=$('#emojiPanel');panel.hidden=!panel.hidden});
$('#emojiPanel').addEventListener('click',e=>{const b=e.target.closest('[data-emoji]');if(!b)return;const input=$('#messageInput'),start=input.selectionStart??input.value.length,end=input.selectionEnd??input.value.length;input.value=input.value.slice(0,start)+b.dataset.emoji+input.value.slice(end);input.focus();input.setSelectionRange(start+b.dataset.emoji.length,start+b.dataset.emoji.length)});
$('#messageForm').addEventListener('submit',async e=>{
 e.preventDefault();$('#emojiPanel').hidden=true;
 const text=$('#messageInput').value.trim();if(!text||!activeChat)return;
 const chatId=activeChat,target=contacts.find(x=>String(x.id)===String(chatId));
 const isChannel=target?.mashixType==='channel';
 const isGroup=target?.mashixType==='group';
 if(isGroup&&supabaseClient&&supabaseUser){
   const input=$('#messageInput');input.disabled=true;
   try{if(!isUuid(chatId))throw new Error('Эта группа пока существует только на этом устройстве. Создай новую группу после входа в аккаунт, чтобы сохранить её на сервере.');await sendRemoteGroupMessage(chatId,text);input.value='';pendingReply=null;window.pendingReplyName=null;input.placeholder='Написать сообщение…';await refreshRemoteGroupChat(chatId);renderChats();}
   catch(error){console.error('MashixTalk group send:',error);alert('Сообщение в группу не отправлено: '+(error.message||'ошибка Supabase'));}
   finally{input.disabled=false;input.focus()}return;
 }
 if(!isChannel&&supabaseClient&&supabaseUser){
   const input=$('#messageInput');input.disabled=true;
   try{
     const remoteId=await resolveRemoteContactId(target,chatId);
     if(!remoteId){
       alert('Не удалось связать этот контакт с реальным аккаунтом Supabase. Открой поиск пользователей и добавь собеседника по точному @никнейму. Сообщение не сохранено локально.');
       return;
     }
     // Replace an old local contact id with the real profile UUID so subsequent
     // opens, reads and sends all use the same conversation in Supabase.
     if(String(chatId)!==remoteId){
       const existing=contacts.find(c=>String(c.id)===remoteId);
       if(!existing){contacts=contacts.map(c=>String(c.id)===String(chatId)?{...c,id:remoteId,isRemote:true}:c);write('gt_contacts',contacts);}
       else {contacts=contacts.filter(c=>String(c.id)!==String(chatId));write('gt_contacts',contacts);}
       activeChat=remoteId;
     }
     await sendRemoteMessage(remoteId,text);
     $('#messageInput').value='';
     await refreshRemoteChat(remoteId);
     renderContacts();renderChats();
   }catch(error){
     console.error('MashixTalk cloud send failed:',error);
     alert('Сообщение не отправлено в облако: '+(error.message||'ошибка Supabase'));
   }finally{input.disabled=false;input.focus();}
   return;
 }
 const arr=[...getMsgs(chatId),{text,mine:true,senderName:(currentUser?.name||currentUser?.username||supabaseUser?.user_metadata?.display_name||'Вы'),at:Date.now(),...(isChannel?{isPost:true,views:1,forwards:0}:{}),...(!isChannel&&pendingReply?{replyTo:pendingReply,replyToName:window.pendingReplyName||'участнику'}:{})}];
 pendingReply=null;window.pendingReplyName=null;$('#messageInput').placeholder='Написать сообщение…';
 const previous=chats;saveMsgs(chatId,arr);
 if(chats===previous){alert('Не удалось сохранить сообщение. Проверь настройки хранилища браузера.');return}
 editingMessageIndex=null;$('#messageInput').value='';renderMessages();renderChats();
 // Автоответ демо-собеседника отключён: входящие сообщения показываются только от реальных отправителей.
});
