chatActionsMenu.addEventListener('click',e=>{
 const btn=e.target.closest('[data-action]');if(!btn||!activeChat)return;
 const action=btn.dataset.action,id=activeChat;
 closeChatActions();
 if(action==='notify'){const m=chatMeta(id);m.muted=!m.muted;setChatMeta(id,m);alert(m.muted?'Уведомления этого чата отключены':'Уведомления этого чата включены');}
 if(action==='search'){
  const q=prompt('Поиск сообщений в этом чате:');if(!q)return;
  const nodes=[...document.querySelectorAll('#messages .bubble')];
  const found=nodes.find(n=>n.textContent.toLocaleLowerCase().includes(q.toLocaleLowerCase()));
  if(found){found.scrollIntoView({block:'center',behavior:'smooth'});found.style.outline='2px solid var(--accent)';setTimeout(()=>found.style.outline='',2500)}else alert('Совпадений среди загруженных сообщений нет.');
 }
 if(action==='wallpaper'){openChatWallpaperEditor(id)}
 if(action==='clear'){
  if(!confirm('Очистить историю этого чата на данном устройстве? Это действие нельзя отменить.'))return;
  saveMsgs(id,[]);renderMessages();renderChats();
 }
 if(action==='delete'){
  if(!confirm('Удалить чат из списка на этом устройстве?'))return;
  saveMsgs(id,[]);contacts=contacts.filter(c=>String(c.id)!==String(id));write('gt_contacts',contacts);
  $('#chatScreen').classList.remove('show');activeChat=null;renderContacts();renderChats();
 }
});
