function usernameError(value){if(value&&!/^[a-zA-Z0-9_]{3,20}$/.test(value))return 'Никнейм: от 3 до 20 символов, только английские буквы, цифры и _.';if(value&&users.some(u=>u.email!==currentUser?.email&&(u.username||'').toLowerCase()===value.toLowerCase()))return 'Это имя пользователя уже занято.';return ''}
$('#editUsername').addEventListener('input',()=>{const input=$('#editUsername');const value=input.value.trim();const error=usernameError(value);$('#usernameFeedback').textContent=error||(value?'Имя пользователя доступно.':'Никнейм можно оставить пустым.');$('#usernameFeedback').style.color=error?'#d45b78':'var(--muted)'});
$('#saveProfile').onclick=async()=>{if(!currentUser)return;let name=$('#editName').value.trim(),username=$('#editUsername').value.trim().replace(/^@/,'').toLowerCase();if(!name){alert('Имя не может быть пустым.');return}const error=usernameError(username);if(error){$('#usernameFeedback').textContent=error;$('#usernameFeedback').style.color='#d45b78';$('#editUsername').focus();return}const feedback=$('#usernameFeedback');const saveButton=$('#saveProfile');saveButton.disabled=true;feedback.textContent='Сохраняю профиль…';feedback.style.color='var(--muted)';try{if(supabaseClient&&supabaseUser){if(username){const {data:matches,error:checkError}=await supabaseClient.from('profiles').select('id').ilike('username',username).neq('id',supabaseUser.id).limit(1);if(checkError)throw checkError;if(matches&&matches.length){feedback.textContent='Этот никнейм уже занят другим аккаунтом.';feedback.style.color='#d45b78';return;}}const {error:saveError}=await supabaseClient.from('profiles').upsert({id:supabaseUser.id,username:username||null,display_name:name,bio:$('#about').value.trim().slice(0,160),avatar_url:currentUser.photo||null,music_url:currentUser.musicUrl||null,music_title:currentUser.musicTitle||null,music_cover_url:currentUser.musicCoverUrl||null,profile_cover_url:currentUser.coverImage||null,profile_cover_color:currentUser.coverColor||null}, {onConflict:'id'});if(saveError)throw saveError;}currentUser.name=name;currentUser.username=username;currentUser.about=$('#about').value.trim().slice(0,160);currentUser.decoration=$('#profileShowcase').dataset.decoration||currentUser.decoration||'sunset';users=users.map(u=>u.email===currentUser.email?currentUser:u);write('gt_users',users);updateProfile();renderContacts();renderChats();feedback.textContent='Профиль сохранён'+(supabaseUser?' в облако.':' на этом устройстве.');feedback.style.color='#28a56a';}catch(err){console.error('Сохранение профиля:',err);feedback.textContent='Не удалось сохранить в облако: '+(err.message||'ошибка Supabase');feedback.style.color='#d45b78';}finally{saveButton.disabled=false;}};
$('#profilePhotoInput').addEventListener('change',async e=>{
  const input=e.currentTarget,file=input.files&&input.files[0];if(!file)return;input.value='';
  if(!file.type||!file.type.startsWith('image/')){$('#photoHint').textContent='Выбери файл изображения.';return}
  if(!currentUser){$('#photoHint').textContent='Сначала войди в аккаунт.';return}
  const ownerEmail=currentUser.email;$('#photoHint').textContent='Обрабатываем фото…';
  try{
    const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('Не удалось прочитать изображение.'));reader.onerror=()=>reject(new Error('Не удалось прочитать изображение.'));reader.readAsDataURL(file)});
    const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Файл изображения повреждён или не поддерживается.'));img.src=dataUrl});
    const maxSide=512,scale=Math.min(1,maxSide/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Браузер не смог обработать изображение.');ctx.drawImage(image,0,0,canvas.width,canvas.height);
    const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Не удалось подготовить изображение.')),'image/jpeg',.78));
    if(!currentUser||currentUser.email!==ownerEmail)return;
    let photoUrl=canvas.toDataURL('image/jpeg',.78);
    if(supabaseClient&&supabaseUser){photoUrl=await uploadProfileMedia(new File([blob],'avatar.jpg',{type:'image/jpeg'}),'avatar');await saveRemoteProfileFields({avatar_url:photoUrl});}
    currentUser.photo=photoUrl;users=users.map(u=>u.email===ownerEmail?currentUser:u);write('gt_users',users);updateProfile();renderContacts();renderChats();
    $('#photoHint').textContent=supabaseUser?'Фото профиля сохранено в облаке':'Фото профиля сохранено на этом устройстве';
  }catch(err){console.error('Фото профиля:',err);$('#photoHint').textContent=err.message||'Не удалось добавить фото. Попробуй другое изображение.'}
});
