// Экспорт и восстановление локальных данных MashixTalk.
const BACKUP_KEYS=['gt_users','gt_contacts','gt_chats','gt_theme'];
function setBackupStatus(message,isError=false){const el=$('#backupStatus');if(el){el.textContent=message;el.style.color=isError?'#ff8b9a':''}}
$('#exportBackup').addEventListener('click',()=>{
  try{
    const payload={app:'MashixTalk',formatVersion:1,createdAt:new Date().toISOString(),data:{}};
    BACKUP_KEYS.forEach(key=>{const raw=localStorage.getItem(key);if(raw!==null)payload.data[key]=JSON.parse(raw)});
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});
    const url=URL.createObjectURL(blob);const a=document.createElement('a');
    a.href=url;a.download='MashixTalk-backup-'+new Date().toISOString().slice(0,10)+'.json';
    document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
    setBackupStatus('Резервная копия подготовлена. Храни файл в безопасном месте.');
  }catch(err){console.error(err);setBackupStatus('Не удалось экспортировать данные. Проверь доступ к хранилищу браузера.',true)}
});
$('#chooseBackup').addEventListener('click',()=>{$('#backupFile').value='';$('#backupFile').click()});
$('#backupFile').addEventListener('change',async e=>{
  const file=e.target.files&&e.target.files[0];if(!file)return;
  try{
    if(file.size>15*1024*1024)throw new Error('Файл слишком большой (лимит 15 МБ).');
    const parsed=JSON.parse(await file.text());
    const data=parsed&&parsed.app==='MashixTalk'&&parsed.formatVersion===1?parsed.data:null;
    if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('Это не резервная копия MashixTalk подходящего формата.');
    if(data.gt_contacts!==undefined&&!Array.isArray(data.gt_contacts))throw new Error('Файл содержит некорректный список контактов.');
    if(data.gt_users!==undefined&&!Array.isArray(data.gt_users))throw new Error('Файл содержит некорректный список аккаунтов.');
    if(data.gt_chats!==undefined&&(!data.gt_chats||typeof data.gt_chats!=='object'||Array.isArray(data.gt_chats)))throw new Error('Файл содержит некорректные переписки.');
    if(data.gt_theme!==undefined&&!['light','dark'].includes(data.gt_theme))throw new Error('Файл содержит некорректную тему.');
    if(!confirm('Восстановить данные из резервной копии? Контакты, переписки, локальные аккаунты и тема на этом устройстве будут заменены данными файла. Сначала экспортируй текущие данные, если хочешь их сохранить.'))return;
    const previous={};BACKUP_KEYS.forEach(k=>previous[k]=localStorage.getItem(k));
    try{
      BACKUP_KEYS.forEach(k=>{if(Object.prototype.hasOwnProperty.call(data,k))localStorage.setItem(k,JSON.stringify(data[k]));else localStorage.removeItem(k)});
    }catch(err){BACKUP_KEYS.forEach(k=>{try{if(previous[k]===null)localStorage.removeItem(k);else localStorage.setItem(k,previous[k])}catch(_){}});throw err}
    users=read('gt_users',[]);contacts=read('gt_contacts',defaultContacts);chats=read('gt_chats',{});
    if(currentUser&&!users.some(u=>u.email===currentUser.email)){currentUser=null;$('#auth').style.display='flex'}
    renderContacts();renderChats();if(activeChat&&contacts.some(c=>c.id===activeChat))renderMessages();else{activeChat=null;$('#chatScreen').classList.remove('show')}
    applyTheme(read('gt_theme','light')==='dark');
    setBackupStatus('Данные восстановлены. Если экран отображается не полностью, перезагрузи страницу.');
  }catch(err){console.error(err);setBackupStatus(err.message||'Не удалось восстановить данные из файла.',true)}finally{e.target.value=''}
});

function applyTheme(dark){document.body.classList.toggle('dark',dark);$('#themeToggle').textContent=dark?'☀️':'🌙';$('#themeToggle').title=dark?'Включить светлую тему':'Включить тёмную тему';$('#themeToggle').setAttribute('aria-label',$('#themeToggle').title);try{localStorage.setItem('gt_theme',dark?'dark':'light')}catch(e){}}
let savedTheme='light';try{savedTheme=localStorage.getItem('gt_theme')||'light'}catch(e){}applyTheme(savedTheme==='dark');
$('#themeToggle').addEventListener('click',()=>applyTheme(!document.body.classList.contains('dark')));
renderChats();renderContacts();
